using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Net;
using System.Net.Mail;
using System.Threading;
using System.Threading.Tasks;

namespace EmailService
{
    public sealed class TenantSmtpPool : IDisposable
    {
        private readonly ConcurrentDictionary<string, PooledClient> _pool = new();
        private readonly ReaderWriterLockSlim _evictionLock = new();
        private volatile bool _disposed;

        public PooledClient Acquire(string tenantId, SmtpConfig config)
        {
            if (_disposed) throw new ObjectDisposedException(nameof(TenantSmtpPool));

            return _pool.GetOrAdd(tenantId, tid =>
            {
                // Do not transmit credentials over an unencrypted connection.
                if (!config.UseTls &&
                    (!string.IsNullOrEmpty(config.Username) || !string.IsNullOrEmpty(config.Password)))
                {
                    throw new InvalidOperationException(
                        "SMTP credentials cannot be used without TLS enabled (cleartext credential exposure).");
                }

                var client = new SmtpClient(config.Host, config.Port)
                {
                    EnableSsl = config.UseTls,
                    Credentials = new NetworkCredential(config.Username, config.Password)
                };
                return new PooledClient(client, tid, this);
            });
        }

        public void EvictTenant(string tenantId)
        {
            _evictionLock.EnterWriteLock();
            try
            {
                if (_pool.TryRemove(tenantId, out var pooled))
                {
                    pooled.MarkEvicted();
                    pooled.Dispose();
                }
            }
            finally
            {
                _evictionLock.ExitWriteLock();
            }
        }

        public void Dispose()
        {
            _disposed = true;
            foreach (var kvp in _pool)
                kvp.Value.Dispose();
            _pool.Clear();
            _evictionLock.Dispose();
        }
    }

    public sealed class PooledClient : IDisposable
    {
        private SmtpClient _client;
        private readonly string _tenantId;
        private readonly TenantSmtpPool _owner;
        private int _refCount;
        private volatile bool _evicted;

        public PooledClient(SmtpClient client, string tenantId, TenantSmtpPool owner)
        {
            _client = client;
            _tenantId = tenantId;
            _owner = owner;
            _refCount = 0;
        }

        public string TenantId => _tenantId;
        public bool IsEvicted => _evicted;

        public SmtpClient BorrowClient()
        {
            Interlocked.Increment(ref _refCount);
            return _client;
        }

        public void ReturnClient()
        {
            Interlocked.Decrement(ref _refCount);
        }

        public void MarkEvicted() => _evicted = true;

        public void Dispose()
        {
            var client = Interlocked.Exchange(ref _client, null);
            client?.Dispose();
        }
    }

    public class SmtpConfig
    {
        public string Host { get; set; }
        public int Port { get; set; }
        public bool UseTls { get; set; }
        public string Username { get; set; }
        public string Password { get; set; }
    }

    public class EmailRequest
    {
        public string TenantId { get; set; }
        public string From { get; set; }
        public string To { get; set; }
        public string Subject { get; set; }
        public string Body { get; set; }
    }

    public class MultiTenantEmailService
    {
        private readonly TenantSmtpPool _pool;
        private readonly ConcurrentDictionary<string, SmtpConfig> _configs;
        private readonly SemaphoreSlim _sendLock = new(10, 10);

        public MultiTenantEmailService(TenantSmtpPool pool, ConcurrentDictionary<string, SmtpConfig> configs)
        {
            _pool = pool;
            _configs = configs;
        }

        public async Task<bool> SendEmailAsync(EmailRequest request, CancellationToken ct)
        {
            if (!_configs.TryGetValue(request.TenantId, out var config))
                throw new UnauthorizedAccessException($"Tenant {request.TenantId} not configured");

            var pooled = _pool.Acquire(request.TenantId, config);

            // Validate tenant isolation
            if (pooled.TenantId != request.TenantId)
                throw new InvalidOperationException("Tenant mismatch detected");

            var client = pooled.BorrowClient();
            await _sendLock.WaitAsync(ct);
            try
            {
                // Simulate async work before send - allows eviction window
                await Task.Delay(10, ct);

                // Check if still valid after delay
                if (pooled.IsEvicted)
                {
                    pooled.ReturnClient();
                    // Re-acquire after eviction
                    pooled = _pool.Acquire(request.TenantId, config);
                    // Correctly re-borrow from the new pooled instance
                    client = pooled.BorrowClient();
                }

                using var message = new MailMessage(request.From, request.To, request.Subject, request.Body);
                message.IsBodyHtml = false;

                client.Send(message);
                return true;
            }
            catch (ObjectDisposedException)
            {
                return false;
            }
            finally
            {
                pooled.ReturnClient();
                _sendLock.Release();
            }
        }

        public void RotateTenantCredentials(string tenantId, SmtpConfig newConfig)
        {
            _configs[tenantId] = newConfig;
            _pool.EvictTenant(tenantId);
        }
    }
}
